const reviews=()=>`<div class="review-grid"><article class="review"><p class="eyebrow">BEST OF ORANGEVALE · 2025</p><h3>A local favorite.</h3><p>First place in Best Pool Sales/Services in the 2025 Best of Orangevale community awards.</p>${a('https://www.bestoforangevale.com/category/10080/best-pool-salesservices','Explore the award ↗','text-link')}</article><article class="review"><p class="eyebrow">NEIGHBOR RECOMMENDATIONS</p><h3>Care people come back to.</h3><p>Neighbors on Nextdoor highlight dependable weekly care, helpful service, and pool equipment expertise.</p>${a(links.Nextdoor,'Read neighbor recommendations ↗','text-link')}</article><article class="review"><p class="eyebrow">PART OF THE COMMUNITY</p><h3>Local roots. Personal service.</h3><p>Based in Orangevale and listed with the Fair Oaks Chamber of Commerce, Pappas Pools serves the greater Sacramento community.</p>${a('https://web03.docu.team/mtiodew/index.php?store=173429&v=lp','View chamber profile ↗','text-link')}</article></div>`;
