const form=()=>`<form id="quote" method="post" action="/api/quote"><div class="form-row"><label>Full name<input name="name" autocomplete="name" maxlength="100" required></label><label>Phone<input name="phone" type="tel" autocomplete="tel" minlength="7" maxlength="30" required></label></div><div class="form-row"><label>Email<input name="email" type="email" autocomplete="email" maxlength="160" required></label><label>ZIP code<input name="zip" autocomplete="postal-code" pattern="[0-9]{5}" maxlength="5" inputmode="numeric" required></label></div><label>What can we help with?<select name="service" required><option value="">Choose a service</option>${services.map(s=>`<option>${s[1]}</option>`).join('')}<option>Not sure yet</option></select></label><label>Tell us about your pool<textarea name="message" rows="4" maxlength="2000" placeholder="Water condition, equipment concerns, or the care you’re looking for."></textarea></label><label class="trap" aria-hidden="true">Leave empty<input name="website" tabindex="-1" autocomplete="off"></label><label class="consent"><input type="checkbox" name="consent" required> I agree to be contacted about this request and have read the <a href="/privacy/">privacy notice</a>.</label><button class="button" type="submit">Request my quote <span>↗</span></button><p class="form-note">No payment required. Service and timing are confirmed after review.</p><p id="form-status" role="status" aria-live="polite"></p></form>`;
