const ar=areas.find(s=>path==='/service-areas/'+slug(s)+'/');if(ar){let notes={Sacramento:'Long swimming seasons, hot summers, and falling leaves make a consistent care routine valuable for Sacramento pools.',Natomas:'Windblown debris and hot valley afternoons can make pool care feel like a second job in Natomas.', 'West Sacramento':'For West Sacramento pool owners, water balance and reliable filtration are the foundation of an inviting backyard.', 'Elk Grove':'From family swim days to quiet evenings by the water, an Elk Grove pool deserves care that fits how you use it.'};return ['Pool Service in '+ar+', CA | Pappas Pools','Request weekly pool maintenance, green-to-clean recovery and equipment help in '+ar+'. Contact Pappas Pools to confirm availability.',hero(ar.toUpperCase()+' POOL SERVICE','More pool time.<br>Less pool work in '+ar+'.',notes[ar]||'Keep your '+ar+' backyard ready for the moments you enjoy most, with pool care tailored to your water and equipment.')+section('LOCAL POOL CARE','A practical plan for your '+ar+' pool.',`<div class="split"><div><p class="large-copy">Ask Pappas Pools about weekly cleaning, chemical balancing, spa maintenance, or help with pool equipment in ${ar}. Share your ZIP code so the team can confirm the route and service options for your property.</p>${btn()}</div><div class="checklist"><h3>What to include in your request</h3><p>✓ Your ZIP code and pool type</p><p>✓ Current water condition</p><p>✓ Equipment or cleaning concerns</p><p>✓ Whether you need one-time or recurring care</p></div></div>`)+section('SERVICE OPTIONS','Care from surface to system.',cards(),'tint')+cta()];}
if(path==='/about/')return ['About Pappas Pools | Pool Care in Sacramento','Learn about Pappas Pools’ pool-specific approach to water chemistry, weekly maintenance, spa care and equipment service in Sacramento.',hero('THE PAPPAS POOLS APPROACH','Good chemistry starts<br>with understanding your pool.','A cleaner pool is the result. Thoughtful, consistent care is how you get there.')+section('CARE WITH PURPOSE','The details make the difference.',`<div class="feature-panel"><img src="/assets/pool.jpg" alt="Bright, clear pool in a residential backyard" loading="lazy"><div><h3>Local service. A practical mindset.</h3><p>Pappas Pools serves pool and spa owners throughout Sacramento and surrounding communities. The team’s published service approach emphasizes water chemistry and care tailored to individual pools.</p><p>Every pool has different demands. Services include weekly maintenance, pool and spa repairs, pool sweep repair and installation, and new pool startups.</p><p>Founded by Josh and Megan Pappas, this family-owned business grew from a small local route into a familiar name in the Orangevale community.</p></div></div>`)+section('OUR FOCUS','Make the care as clear as the water.',`<div class="steps"><div><h3>Understand first</h3><p>Look at the condition of the water, the equipment, and how the pool is used.</p></div><div><h3>Explain the options</h3><p>Discuss service scope and the chemical charges relevant to your pool.</p></div><div><h3>Build a routine</h3><p>Choose ongoing care that helps your pool stay part of your life, rather than another chore.</p></div></div>`,'tint')+cta()];
if(path==='/reviews/')return ['Pappas Pools Customer Reviews | Sacramento Pool Service','Read summaries of real Pappas Pools customer feedback and visit Google, Nextdoor and community sources.',hero('CUSTOMER EXPERIENCES','A reputation built<br>one backyard at a time.','Helpful answers, responsive service, and cleaner water are recurring themes in Pappas Pools’ published customer feedback.')+section('WHAT CUSTOMERS SHARE','The care behind the clear water.',reviews()+`<div class="review-sources"><h3>Explore the original reviews</h3><p>These are paraphrased summaries, not verbatim quotations. Ratings and review counts on third-party platforms can change.</p>${a(links.Nextdoor,'Read Nextdoor recommendations ↗','text-link')} ${a(google,'View Google listing ↗','text-link')} </div>`)+cta()];
if(path==='/faq/')return ['Pool Service FAQs | Pappas Pools Sacramento','Answers about Pappas Pools weekly pool service, pricing, green water recovery, spa care and Sacramento service availability.',hero('POOL CARE QUESTIONS','Clear answers.<br>Before you take the plunge.','Find a starting point here, then talk with the team about your specific pool.')+section('FREQUENTLY ASKED','What would you like to know?',faqs())+cta()];
if(path==='/contact/')return ['Request a Pool Service Quote | Pappas Pools Sacramento','Contact Pappas Pools at (916) 220-7799 or request a pool cleaning, maintenance, spa or equipment repair quote online.',hero('LET’S TALK ABOUT YOUR POOL','One small step.<br>A clearer pool ahead.','Tell us what is happening with your pool. No payment required to request a quote.')+section('REQUEST SERVICE','What can we take off your hands?',`<div class="contact-grid"><div><h3>Prefer a conversation?</h3><a class="phone" href="tel:+19162207799">(916) 220-7799</a><p>${a('mailto:pappaspools@gmail.com','pappaspools@gmail.com')}</p><div class="contact-info"><b>Published office hours</b><p>Monday–Friday: 8 am–5 pm<br>Saturday: Closed<br>Sunday: Closed</p><b>Sacramento & surrounding areas</b><p>Share your ZIP code to confirm route availability. Appointments are confirmed directly.</p></div><p>Need urgent help? Call the team. Online requests are not an emergency service.</p></div><div class="form-card">${form()}</div></div>`)+section('STAY CONNECTED','Find Pappas Pools around the web.',`<div class="area-links">${Object.entries(links).map(([n,l])=>a(l,n+' ↗')).join('')}${a(google,'Google Maps ↗')}</div>`,'tint')];
if(path==='/privacy/')return ['Privacy Notice | Pappas Pools','How this Pappas Pools website handles service inquiries and contact information.',hero('PRIVACY','Your request.<br>Your information.','Last updated October 21, 2026.')+section('CONTACT FORM PRIVACY','How information is handled.',`<div class="prose"><p>This website collects the name, phone number, email, ZIP code, chosen service, and message you submit to request pool care. Do not include payment information or sensitive personal details.</p><p>Requests are stored securely by the website’s hosting infrastructure for authorized website operators to review and facilitate a response. This website does not take payments or confirm appointments automatically. Information is used to respond to your inquiry and is not sold.</p><p>No advertising trackers or non-essential cookies are installed by this website. External social and review links have their own privacy policies.</p><p>For questions or to request removal of your inquiry, contact pappaspools@gmail.com. Website operators should remove inquiries once no longer needed for the service request.</p></div>`)];
