const js=`const toggle=document.querySelector('.menu'), navigation=document.querySelector('nav');const closeMenu=()=>{navigation?.classList.remove('open');toggle?.setAttribute('aria-expanded','false')};toggle?.addEventListener('click',()=>{const open=navigation.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open))});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();toggle?.focus()}});document.addEventListener('click',e=>{if(!e.target.closest('.header'))closeMenu()});navigation?.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.querySelector('#quote')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),s=document.querySelector('#form-status');b.disabled=true;b.textContent='Submitting…';s.textContent='';try{let r=await fetch('/api/quote',{method:'POST',body:new FormData(f)});let d=await r.json();if(!r.ok)throw new Error(d.error||'Please try again.');f.reset();s.textContent='Your request is saved. Reference: '+d.reference+'. For time-sensitive help, call (916) 220-7799.';}catch(err){s.textContent=err.message+' You can also call (916) 220-7799.';}finally{b.disabled=false;b.textContent='Request my quote ↗';}});`;
function page(path){let [title,desc,body]=content(path);let schema={'@context':'https://schema.org','@type':'LocalBusiness',name:'Pappas Pools',url:origin,telephone:'+19162207799',email:'pappaspools@gmail.com',address:{'@type':'PostalAddress',streetAddress:'6326 Main Avenue, Unit 12',addressLocality:'Orangevale',addressRegion:'CA',postalCode:'95662',addressCountry:'US'},openingHours:['Mo-Fr 08:00-17:00'],logo:origin+'/assets/logo.png',areaServed:areas,sameAs:Object.values(links),description:'Pool cleaning, maintenance, equipment repair and spa service in Sacramento and surrounding communities.'};return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>${title}</title><meta name="description" content="${desc}"><link rel="canonical" href="${origin+path}"><meta name="theme-color" content="#101c25"><meta property="og:type" content="website"><meta property="og:site_name" content="Pappas Pools"><meta property="og:title" content="${path==='/'?'Pappas Pools | Sacramento':title}"><meta property="og:description" content="${desc}"><meta property="og:url" content="${origin+path}"><meta property="og:image" content="https://pappas-pools.roundprawn256.chatgpt.site/assets/pappas-preview-v1.jpg"><meta property="og:image:alt" content="Pappas Pools website homepage with pool photography and the words Your pool. Your happy place."><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="https://pappas-pools.roundprawn256.chatgpt.site/assets/pappas-preview-v1.jpg"><link rel="icon" href="/favicon.svg"><style>${css}</style><script type="application/ld+json">${JSON.stringify(schema)}</script></head><body><a href="#main" class="skip">Skip to content</a><div class="topbar"><div class="wrap">SACRAMENTO & SURROUNDING COMMUNITIES <span>LESS POOL WORK. MORE POOL DAYS.</span>${a('tel:+19162207799','(916) 220-7799')}</div></div><header class="header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="Pappas Pools home">${crown}<div><strong>PAPPAS POOLS</strong><small>POOLS &amp; SPAS</small></div></a><button class="menu" aria-label="Toggle navigation" aria-controls="nav" aria-expanded="false">Menu ☰</button><nav id="nav" aria-label="Main navigation">${nav.map(([h,l])=>a(h,l)).join('')}${a('/contact/','Get a quote ↗','nav-cta')}</nav></div></header><main id="main">${body}</main><footer class="footer"><div class="wrap"><div class="footer-grid"><div><a href="/" class="brand">${crown}<div><strong>PAPPAS POOLS</strong><small>POOLS &amp; SPAS</small></div></a><p>Your pool. Your happy place.<br>Pool and spa care for Sacramento and surrounding communities.</p>${a('tel:+19162207799','(916) 220-7799')}${a('mailto:pappaspools@gmail.com','pappaspools@gmail.com')}</div><div><h3>Pool & spa care</h3>${services.map(s=>a('/services/'+s[0]+'/',s[1])).join('')}</div><div><h3>Explore</h3>${nav.map(([h,l])=>a(h,l)).join('')}${a('/faq/','FAQs')}${a('/contact/','Request a quote')}</div><div><h3>Stay connected</h3>${Object.entries(links).map(([n,l])=>a(l,n+' ↗')).join('')}${a(google,'Google Maps ↗')}</div></div><div class="footer-bottom"><span>© 2026 Pappas Pools</span>${a('/privacy/','Privacy notice')}<span>Thoughtful care. Clearer water.</span></div><div class="preview-note">Website concept prepared for Pappas Pools. Pool imagery is illustrative. Service availability and quotations are confirmed directly.</div></div></footer><div class="mobile-bar">${a('tel:+19162207799','Call Pappas Pools')}${a('/contact/','Get a quote ↗')}</div><script>${js}</script></body></html>`}


